        const emitter = parseNLPQueryStream(response.body);
        let finished = false;
        let results = [];
        emitter.on('search_results', (event) => {
            results = event.results;
            finished = true;
        });
        emitter.on('error', (e) => {
            if (e.is_terminal) {
                finished = true;
            }
            throw new Error(e.error);
        });
